import{_ as a}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{C as c,c as i,o as e,ag as o,b as s,w as r,a as n,G as l,ah as g}from"./chunks/mermaid.Bf0DxEx6.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"企业代码开发最佳实践与落地蓝图","description":"融合 Superpowers、OpenSpec、Spec Kit 与 mattpocock/skills 的核心经验，提炼 AI 时代代码开发六大工程支柱、按风险与协作形态分层的落地路线，以及可复现的单仓试点流水线。","frontmatter":{"title":"企业代码开发最佳实践与落地蓝图","description":"融合 Superpowers、OpenSpec、Spec Kit 与 mattpocock/skills 的核心经验，提炼 AI 时代代码开发六大工程支柱、按风险与协作形态分层的落地路线，以及可复现的单仓试点流水线。","domain":"practice","tags":["enterprise","best-practices","sdd","harness-engineering"]},"headers":[],"relativePath":"zh/practice/sdd-engineering/enterprise-best-practices.md","filePath":"zh/practice/sdd-engineering/enterprise-best-practices.md","lastUpdated":1795764761000}'),p={name:"zh/practice/sdd-engineering/enterprise-best-practices.md"};function E(h,t,A,m,B,b){const d=c("Mermaid");return e(),i("div",null,[t[1]||(t[1]=o('<h1 id="企业代码开发最佳实践与落地蓝图" tabindex="-1">企业代码开发最佳实践与落地蓝图 <a class="header-anchor" href="#企业代码开发最佳实践与落地蓝图" aria-label="Permalink to &quot;企业代码开发最佳实践与落地蓝图&quot;">​</a></h1><p><strong>结论先行（BLUF）</strong>：当前企业级 AI 代码开发的成熟实践，正在从「调教更好的 Prompt」收敛为 <strong>SDD（Spec-Driven Development，规格驱动开发）+ Harness Engineering（确定性工程护栏）</strong>。企业不应把质量完全押注在单一工具或 Agent 的「自觉性」上，而应采用**「人类掌控需求与架构边界 + 宪法与 Delta Spec 管住组织红线与存量真源 + 自动化测试与受保护分支 CI 锁死交付门禁」**的分层体系。</p><h2 id="先决条件" tabindex="-1">先决条件 <a class="header-anchor" href="#先决条件" aria-label="Permalink to &quot;先决条件&quot;">​</a></h2><ul><li>已阅读前两篇：<a href="./tools-comparison.html">深度对比</a> 与 <a href="./sdd-quality-assurance.html">SDD 质量保证机制</a>。</li><li>团队已具备基础的 Git 受保护分支（Protected Branch）、CI/CD 流水线与自动化测试运行环境。</li></ul><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><p>读完本文，你将能够：</p><ol><li>掌握 AI 时代代码开发的 <strong>6 大核心工程支柱</strong> 及其不可逾越的反模式（NEVER）。</li><li>根据<strong>变更风险与组织协作形态</strong>（而非单纯按人数）选择匹配的 SDD 组合方案。</li><li>直接复现一条<strong>从固定规格到 CI 门禁合并</strong>的最小单仓试点流水线。</li></ol><hr><h2 id="一、目前代码开发最佳实践的-6-大核心支柱" tabindex="-1">一、目前代码开发最佳实践的 6 大核心支柱 <a class="header-anchor" href="#一、目前代码开发最佳实践的-6-大核心支柱" aria-label="Permalink to &quot;一、目前代码开发最佳实践的 6 大核心支柱&quot;">​</a></h2><p>综合 <code>obra/superpowers</code>、<code>Fission-AI/OpenSpec</code>、<code>github/spec-kit</code> 与 <code>mattpocock/skills</code> 的核心机制，高可靠 AI 研发体系建立在以下六根支柱之上：</p><table tabindex="0"><thead><tr><th>支柱</th><th>核心原则</th><th>反模式（NEVER）</th><th>可落地的最小实践</th></tr></thead><tbody><tr><td><strong>1. Spec-First 与增量真源</strong></td><td>先定行为契约再写代码；存量项目用 Delta Spec 持续同步主规格</td><td><strong>NEVER</strong> 需求模糊时让 AI 直接改代码；<strong>NEVER</strong> 让文档与代码长期双轨脱节</td><td>用 <code>OpenSpec</code> 管理变更提案与增量规格，合入后同步归档</td></tr><tr><td><strong>2. 通用语言与宪法/ADR 护栏</strong></td><td>团队与 AI 共享同一套领域词表与不可协商底线</td><td><strong>NEVER</strong> 让 AI 凭猜测发明同义变量名，或每次会话推翻既有架构红线</td><td>维护 <code>GLOSSARY.md</code>（术语表）、<code>docs/adr/</code> 与 <code>.specify/memory/constitution.md</code></td></tr><tr><td><strong>3. 垂直示踪弹切片与隔离</strong></td><td>按「端到端可验证垂直切片（Tracer Bullet）」拆任务，隔离并发工作区</td><td><strong>NEVER</strong> 按技术层（全端 DTO→DAO→UI）水平切片；<strong>NEVER</strong> 多任务并发写同一工作目录</td><td>用任务依赖图（DAG）拆出带阻塞边的 Ticket，高并发时在独立 <code>git worktree</code> 执行</td></tr><tr><td><strong>4. Seam 边界 TDD 与新鲜证据</strong></td><td>在人类预确认的公共接口（Seam）做红-绿测试；无新鲜命令输出不宣称完工</td><td><strong>NEVER</strong> 写耦合内部私有方法的测试；<strong>NEVER</strong> 在未跑最新测试/构建时说「应该好了」</td><td>强制 <code>Red → Green</code> 循环，交付必须附带最新 Commit 上的命令退出码与输出</td></tr><tr><td><strong>5. 双轴独立 Review 与定期熵减</strong></td><td>「是否符合规范」与「是否满足 Spec」独立审查；周期性深化模块边界</td><td><strong>NEVER</strong> 用「代码格式漂亮」掩盖需求漏项；<strong>NEVER</strong> 放任 AI 堆砌浅层胶水代码</td><td>配置 <code>Standards</code> + <code>Spec</code> 双轴审查；按团队节奏（可选每周）运行架构巡检</td></tr><tr><td><strong>6. Harness 自进化与 CI 硬门禁</strong></td><td>把重复踩坑固化为 Linter/CI 脚本，区分「Agent 提示」与「分支硬门禁」</td><td><strong>NEVER</strong> 把一次性教训留在聊天记录里，或指望提示词替代 CI 拦截</td><td>任务后用 <code>retro</code> 提炼改进项；把静态校验、测试与例外审批接入 CI 合并门禁</td></tr></tbody></table><hr><h2 id="二、分层落地路线-按风险等级与协作形态选型" tabindex="-1">二、分层落地路线：按风险等级与协作形态选型 <a class="header-anchor" href="#二、分层落地路线-按风险等级与协作形态选型" aria-label="Permalink to &quot;二、分层落地路线：按风险等级与协作形态选型&quot;">​</a></h2><p>企业落地切忌按人数拍脑袋，而应按<strong>变更风险、跨仓依赖与合规要求</strong>分层配置：</p><h3 id="场景-a-低风险单仓-独立开发者与小团队" tabindex="-1">场景 A：低风险单仓 / 独立开发者与小团队 <a class="header-anchor" href="#场景-a-低风险单仓-独立开发者与小团队" aria-label="Permalink to &quot;场景 A：低风险单仓 / 独立开发者与小团队&quot;">​</a></h3><ul><li><strong>核心风险</strong>：需求没想清就开写、测试耦合内部实现、代码两周后腐化为大泥球。</li><li><strong>推荐组合</strong>：<code>mattpocock/skills</code>（<code>/grill-with-docs</code> + <code>tdd</code> + <code>code-review</code>）+ <code>obra/superpowers</code> 质量铁律（<code>verification-before-completion</code>）。</li><li><strong>落地重点</strong>： <ol><li>复杂改动前先跑 <code>/grill-with-docs</code> 对齐设计树并更新 <code>GLOSSARY.md</code>。</li><li>编码前先让人类确认测试 Seam，按垂直切片做红-绿测试。</li><li>仅在必要时（如长任务防压缩）引入磁盘进度账本。</li></ol></li></ul><h3 id="场景-b-多人并发的存量业务单仓-brownfield" tabindex="-1">场景 B：多人并发的存量业务单仓（Brownfield） <a class="header-anchor" href="#场景-b-多人并发的存量业务单仓-brownfield" aria-label="Permalink to &quot;场景 B：多人并发的存量业务单仓（Brownfield）&quot;">​</a></h3><ul><li><strong>核心风险</strong>：多人/多 Agent 并发修改同一存量仓库，彼此踩踏既有系统行为，或并发改同一份 Spec 产生冲突。</li><li><strong>推荐组合</strong>：<code>Fission-AI/OpenSpec</code>（单仓 Delta Spec）+ <code>obra/superpowers</code>（Worktree 隔离与账本）+ <code>mattpocock/skills</code>（<code>code-review</code> / <code>improve-codebase-architecture</code>）。</li><li><strong>落地重点</strong>： <ol><li>并发修改同一规格时，必须明确<strong>规格所有者（Owner）与版本基线</strong>，并在集成后复核主规格一致性。</li><li>在 CI 中对在途变更运行 <code>openspec validate &lt;change-id&gt; --type change --strict --no-interactive</code>（或批量 <code>--changes --strict --no-interactive</code>），但<strong>同时要求关联的自动化测试全部通过</strong>。</li><li>定期（如双周或每周五，属团队可选策略）运行 <code>/improve-codebase-architecture</code> 清理浅层封装与重复逻辑。</li></ol></li></ul><h3 id="场景-c-跨仓微服务-强合规与离线组织" tabindex="-1">场景 C：跨仓微服务 / 强合规与离线组织 <a class="header-anchor" href="#场景-c-跨仓微服务-强合规与离线组织" aria-label="Permalink to &quot;场景 C：跨仓微服务 / 强合规与离线组织&quot;">​</a></h3><ul><li><strong>核心风险</strong>：外部 API/Schema 契约变更破坏下游、敏感或不可逆操作缺少审批、私有化/离线环境无法使用公网组件。</li><li><strong>推荐组合</strong>：<code>github/spec-kit</code>（<code>.specify/memory/constitution.md</code> + Preset/私有 Catalog）+ <code>Fission-AI/OpenSpec</code> Stores（beta）+ Issue Tracker DAG。</li><li><strong>落地重点</strong>： <ol><li>用 <code>spec-kit</code> 的 <strong>Preset / Private Catalog</strong> 下发组织级宪法与合规检查清单。</li><li>对外部契约变更，额外补充<strong>兼容性矩阵、部署顺序、回滚与数据迁移验收</strong>；对敏感或不可逆变更，强制<strong>人工审批记录与脱敏证据</strong>。</li><li>若使用 OpenSpec **Stores（beta）**共享跨仓规格，需明确其仅提供只读 <code>references</code> 上下文，<strong>不能替代 Git 同步、跨仓版本固定（Pinning）或联调集成验收</strong>。</li></ol></li></ul><hr><h2 id="三、可复现试点-三工具单仓实战流水线" tabindex="-1">三、可复现试点：三工具单仓实战流水线 <a class="header-anchor" href="#三、可复现试点-三工具单仓实战流水线" aria-label="Permalink to &quot;三、可复现试点：三工具单仓实战流水线&quot;">​</a></h2><p>下面是一条可直接照搬的**「三工具单仓试点流水线（mattpocock/skills + OpenSpec + superpowers）」<strong>，严格遵循</strong>「固定规格版本 → 实施提交 → 对该提交审查与 CI → 获授权合并 → 归档并读回」**的不可逆顺序（若团队同时引入 <code>spec-kit</code>，可在阶段 1 之前叠加 <code>.specify/memory/constitution.md</code> 审查）：</p>',23)),(e(),s(g,null,{default:r(()=>[l(d,{id:"mermaid-280",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%221.%20%E5%AF%B9%E9%BD%90%E4%B8%8E%E8%AF%8D%E6%B1%87%E6%B2%89%E6%B7%80%3Cbr%2F%3E%2Fgrill-with-docs%3Cbr%2F%3E%E4%BA%A7%E5%87%BA%3A%20GLOSSARY.md%20%26%20ADR%22%5D%20--%3E%20B%5B%222.%20%E8%A7%84%E6%A0%BC%E8%90%BD%E7%9B%98%E4%B8%8E%E7%89%88%E6%9C%AC%E5%9B%BA%E5%AE%9A%3Cbr%2F%3EOpenSpec%20propose%3Cbr%2F%3E%E4%BA%A7%E5%87%BA%3A%20proposal%2Fspecs%2Fdesign%2Ftasks%3Cbr%2F%3E%E9%97%A8%E7%A6%81%3A%20openspec%20validate%20--strict%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%223.%20%E9%9A%94%E7%A6%BB%E5%88%87%E7%89%87%E4%B8%8E%20TDD%20%E6%8F%90%E4%BA%A4%3Cbr%2F%3Egit%20worktree%20%2B%20Seam%20TDD%3Cbr%2F%3E%E4%BA%A7%E5%87%BA%3A%20%E5%8F%AF%E6%B5%8B%20Commit%20SHA%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%224.%20%E5%8F%8C%E8%BD%B4%E5%AE%A1%E6%9F%A5%E4%B8%8E%20CI%20%E7%A1%AC%E9%97%A8%E7%A6%81%3Cbr%2F%3Ecode-review(fixed-point..HEAD)%3Cbr%2F%3E%2B%20%E6%B5%8B%E8%AF%95%2F%E6%9E%84%E5%BB%BA%E9%80%80%E5%87%BA%E7%A0%81%200%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%225.%20%E4%BA%BA%E5%B7%A5%E6%94%BE%E8%A1%8C%E4%B8%8E%E5%BD%92%E6%A1%A3%E8%AF%BB%E5%9B%9E%3Cbr%2F%3E%E5%90%88%E5%B9%B6%20PR%20%E2%86%92%20archive%20%E5%90%8C%E6%AD%A5%E4%B8%BB%E8%A7%84%E6%A0%BC%3Cbr%2F%3E%E2%86%92%20%E9%AA%8C%E8%AF%81%E4%B8%BB%E8%A7%84%E6%A0%BC%E5%B7%B2%E6%9B%B4%E6%96%B0%22%5D%0A"})]),fallback:r(()=>[...t[0]||(t[0]=[n(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=o('<h3 id="最小试点执行清单-输入-→-产物-→-证据-→-人工接管点" tabindex="-1">最小试点执行清单（输入 → 产物 → 证据 → 人工接管点） <a class="header-anchor" href="#最小试点执行清单-输入-→-产物-→-证据-→-人工接管点" aria-label="Permalink to &quot;最小试点执行清单（输入 → 产物 → 证据 → 人工接管点）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>阶段</th><th>输入</th><th>核心产物</th><th>可验证证据 / 命令</th><th>人工接管点</th></tr></thead><tbody><tr><td><strong>1. 对齐</strong></td><td>原始业务需求</td><td><code>GLOSSARY.md</code>、ADR</td><td>设计树无未决分支</td><td>确认 Non-Goals 与核心术语</td></tr><tr><td><strong>2. 契约</strong></td><td>对齐结论</td><td><code>openspec/changes/&lt;id&gt;/</code> 四件套</td><td><code>openspec validate &lt;id&gt; --type change --strict --no-interactive</code> 退出码 <code>0</code></td><td>审批 <code>proposal.md</code> 与测试 Seam（固定 Spec 版本）</td></tr><tr><td><strong>3. 实施</strong></td><td>固定后的 Spec + <code>tasks.md</code></td><td>独立 Worktree 分支上的 Commit</td><td>每个切片先红灯（预期行为失败）后绿灯；若遇无法保持绿灯的宽重构，采用 <strong>Expand–Contract</strong>（先扩展兼容→分批迁移→再收缩删旧）</td><td>遇破坏性/安全边界决策时停下由人裁决</td></tr><tr><td><strong>4. 审查与 CI</strong></td><td><code>git diff &lt;base&gt;...HEAD</code> + 固定 Spec</td><td>双轴 Review 报告（Standards + Spec）</td><td>CI 执行全量单测 + 构建退出码 <code>0</code>；核对 Review 未跳过 Spec 轴</td><td>人工复核双轴报告与合并风险（单向门 vs 双向门）</td></tr><tr><td><strong>5. 归档</strong></td><td>已合并的主干代码</td><td>更新后的 <code>openspec/specs/</code></td><td>执行 <code>archive</code> 后读回 <code>openspec show &lt;spec-id&gt; --type spec</code> 确认主规格已同步</td><td>确认主规格与线上行为一致；运行 <code>/retro</code> 沉淀新规则</td></tr></tbody></table><hr><h2 id="四、企业引入常见陷阱与护栏-guardrails" tabindex="-1">四、企业引入常见陷阱与护栏（Guardrails） <a class="header-anchor" href="#四、企业引入常见陷阱与护栏-guardrails" aria-label="Permalink to &quot;四、企业引入常见陷阱与护栏（Guardrails）&quot;">​</a></h2><ol><li><strong>NEVER 用重型流程覆盖微小型改动</strong>：改一个文案或样式色值，直接修改并跑通验证即可；只有涉及跨模块、状态流转或存量行为变更时才走完整 SDD。</li><li><strong>NEVER 混淆「Agent 提示」与「CI 硬门禁」</strong>：Agent 可能会因确认跳过 <code>archive</code> 中的未完成任务，或在 YAML 解析失败时跳过 Hook；所有阻断性质量红线必须配置在受保护分支的 CI 必过检查中，例外审批需单独留痕。</li><li><strong>NEVER 在未提交时跑基于 Commit Diff 的 Review</strong>：<code>mattpocock/skills</code> 的 <code>code-review</code> 依赖 <code>git diff &lt;fixed-point&gt;...HEAD</code>，务必先形成完整 Commit 再触发审查，并核对 Spec 轴未被静默跳过。</li><li><strong>NEVER 忽视周期性架构熵减</strong>：AI 极易快速堆出浅层封装与重复分支；若不定期做模块深化与坏味道清理，后续 Agent 的上下文检索与修改成本会持续攀升。</li></ol><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>如果你想先评估团队采购与模型选型预算，可以结合阅读 <a href="/zh/practice/procurement-plan.html">采购与实施方案</a> 与 <a href="/zh/practice/reporter.html">Vibe Coding 报告</a>。</li><li>如果你准备在项目中启动最小试点： <ol><li>在仓库初始化 <code>GLOSSARY.md</code> 与精简的 <code>AGENTS.md</code>；</li><li>选取一个低风险存量特性，按第三节表格跑通一次 <code>OpenSpec</code> 校验 + Seam TDD + CI 硬门禁闭环。</li></ol></li></ul>',7))])}const k=a(p,[["render",E]]);export{f as __pageData,k as default};
